#include <set>
#include <iostream>
#include <utility>

int main() {
    std::multiset<int> c = {1, 2, 2, 4, 5};

    // Search for range of '2'
    auto range2 = c.equal_range(2);
    std::cout << "Elements equal to 2:\n";
    for (auto it = range2.first; it != range2.second; ++it) {
        std::cout << *it << " ";
    }
    std::cout << "\n";

    // Check for 3 (not present)
    auto range3 = c.equal_range(3);
    if (range3.first == range3.second) {
        std::cout << "Element 3 not found.\n";
    }
}
